synchronized (lock) {
    if (!conditionReady) {   // sprawdzone RAZ
        lock.wait();
    }
    // praca zakladajaca, ze conditionReady == true
}
// Problem: jesli watek obudzi sie przez spurious wakeup ZANIM warunek naprawde jest true,
// kod PO wait() i tak zostanie wykonany - if nie sprawdza warunku PONOWNIE po przebudzeniu!

synchronized (lock) {
    while (!conditionReady) {   // sprawdzane PONOWNIE po kazdym obudzeniu
        lock.wait();
    }
    // tu mamy PEWNOSC, ze conditionReady == true
}
// Petla while gwarantuje: niezaleznie OD CZEGO watek sie obudzil (prawdziwy notify,
// spurious wakeup, obudzenie 'przez pomylke'), warunek jest sprawdzany PONOWNIE.

Thread waiter = new Thread(() -> {
    synchronized (lock) {
        while (!conditionReady) {
            lock.wait(2000); // bounded wait - bezpieczenstwo
        }
        System.out.println("warunek SPELNIONY - kontynuuje prace");
    }
});
waiter.start();
Thread.sleep(200);
synchronized (lock) { lock.notifyAll(); } // FALSZYWE obudzenie, BEZ ustawienia warunku!
Thread.sleep(200);
synchronized (lock) { conditionReady = true; lock.notifyAll(); } // TERAZ naprawde

