boolean verifySafeWaitPattern() throws InterruptedException {
    Object lock = new Object();
    boolean[] ready = {false};
    Thread czekajacy = new Thread(() -> { synchronized(lock) { while(!ready[0]) { try { lock.wait(2000); } catch (Exception e) {} } } });
    czekajacy.start();
    Thread.sleep(20);
    synchronized(lock) { lock.notifyAll(); } // falszywe
    Thread.sleep(20);
    synchronized(lock) { ready[0]=true; lock.notifyAll(); } // prawdziwe
    czekajacy.join(2_000);
    return !czekajacy.isAlive() && ready[0];
}
